#!/usr/bin/env bash
#
# Verify Tauri capability configuration for main/detail windows.
#
# This script checks that:
# 1. Generated permissions exist for all commands
# 2. main.json only allows main-window commands
# 3. detail.json only allows detail_* commands
# 4. High-risk commands are NOT in detail.json
#
# Usage:
#   scripts/verify-tauri-capabilities.sh
#
# Exit codes:
#   0 - All checks pass
#   1 - Verification failed
set -euo pipefail

cd "$(dirname "$0")/.."

errors=0

printf 'Verifying Tauri capability configuration...\n\n'

# 1. Check that autogenerated permissions exist
printf '1. Checking autogenerated permissions... '
expected_commands=(
  "check_ollama"
  "export_diagnostics"
  "get_diagnostics"
  "get_local_ai_status"
  "get_runtime_status"
  "get_settings"
  "save_settings"
  "set_autostart"
  "list_models"
  "test_model"
  "library_delete"
  "library_distinct_apps"
  "library_distinct_source_languages"
  "library_distinct_tags"
  "library_distinct_target_languages"
  "library_export"
  "library_export_json"
  "library_export_jsonl"
  "library_get"
  "library_get_tags"
  "library_import_jsonl"
  "library_later_count"
  "library_query"
  "library_review_session"
  "library_secure_wipe"
  "library_set_review_state"
  "library_set_tags"
  "library_update_note"
  "history_count"
  "history_delete"
  "history_list"
  "history_promote"
  "history_prune"
  "recent_list"
  "mori_send_item"
  "mori_status"
  "request_pause_toggle"
  "request_quit"
  "detail_copy"
  "detail_open_in_library"
  "detail_read"
  "detail_request_explain"
  "detail_save"
  "detail_save_note"
)

missing=0
for cmd in "${expected_commands[@]}"; do
  if [[ ! -f "apps/lens/permissions/autogenerated/${cmd}.toml" ]]; then
    printf '\n  - missing permission file for: %s' "$cmd"
    missing=$((missing + 1))
  fi
done

if [[ $missing -eq 0 ]]; then
  printf 'OK (%d commands)\n' "${#expected_commands[@]}"
else
  printf '\nFAILED (%d missing)\n' "$missing"
  errors=$((errors + 1))
fi

# 2. Check that detail.json only has detail_* permissions
printf '2. Checking detail.json permissions... '
if [[ ! -f "apps/lens/capabilities/detail.json" ]]; then
  printf 'FAILED (file not found)\n'
  errors=$((errors + 1))
else
  # Extract all allow-* permissions from detail.json
  detail_perms=$(grep -oE '"allow-[^"]+"' apps/lens/capabilities/detail.json | sed 's/"//g' | sort)

  # Check that all are detail_* commands
  non_detail=0
  while IFS= read -r perm; do
    if [[ ! "$perm" =~ ^allow-detail- ]]; then
      printf '\n  - detail.json has non-detail permission: %s' "$perm"
      non_detail=$((non_detail + 1))
    fi
  done <<< "$detail_perms"

  if [[ $non_detail -eq 0 ]]; then
    printf 'OK (only detail_* permissions)\n'
  else
    printf '\nFAILED (%d non-detail permissions)\n' "$non_detail"
    errors=$((errors + 1))
  fi
fi

# 3. Check that high-risk commands are NOT in detail.json
printf '3. Checking high-risk commands excluded from detail... '
high_risk=(
  "library_secure_wipe"
  "request_quit"
  "set_autostart"
  "save_settings"
  "mori_send_item"
)

leaked=0
for cmd in "${high_risk[@]}"; do
  if grep -q "allow-${cmd//_/-}" apps/lens/capabilities/detail.json 2>/dev/null; then
    printf '\n  - high-risk command leaked to detail: %s' "$cmd"
    leaked=$((leaked + 1))
  fi
done

if [[ $leaked -eq 0 ]]; then
  printf 'OK (none leaked)\n'
else
  printf '\nFAILED (%d leaked)\n' "$leaked"
  errors=$((errors + 1))
fi

# 4. Check that main.json has expected main commands
printf '4. Checking main.json has main commands... '
if [[ ! -f "apps/lens/capabilities/main.json" ]]; then
  printf 'FAILED (file not found)\n'
  errors=$((errors + 1))
else
  main_count=$(grep -c '"allow-' apps/lens/capabilities/main.json || echo 0)
  if [[ $main_count -gt 30 ]]; then
    printf 'OK (%d permissions)\n' "$main_count"
  else
    printf 'FAILED (only %d permissions, expected >30)\n' "$main_count"
    errors=$((errors + 1))
  fi
fi

# 5. Verify capability schema was generated
printf '5. Checking capability schema generation... '
schema_file="target/debug/build/lens-*/out/generated/capability-schema.json"
if ls $schema_file >/dev/null 2>&1; then
  printf 'OK (schema generated)\n'
else
  printf 'SKIPPED (schema not found, may not be generated in dev builds)\n'
fi

# Summary
printf '\n'
if [[ $errors -eq 0 ]]; then
  printf '✓ All capability checks passed\n'
  exit 0
else
  printf '✗ %d capability check(s) failed\n' "$errors"
  exit 1
fi
